css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .sumas-grid{display: grid; grid-template-columns: repeat(4, 1fr); row-gap: 46px; justify-items: center; margin-top: 6px;}
.mz .op{font-family: sans-serif; font-weight: 700;}
.mz .op .fila{display: grid; grid-template-columns: 22px 26px 26px; align-items: center; font-size: 25px;}
.mz .op .fila span{text-align: center;}
.mz .op .signo{font-weight: 800; font-size: 22px;}
.mz .op .circ-fila{display: grid; grid-template-columns: 22px 26px 26px; margin-bottom: 4px;}
.mz .op .circulo{grid-column: 2; width: 24px; height: 24px; border: 1.5px solid var(--bosque); border-radius: 50%; justify-self: center;}
.mz .op .barra{grid-column: 2 / 4; border-top: 2.5px solid var(--bosque); height: 34px;}
